package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ManagedVO;

@RequiredArgsConstructor
public class ManagedValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ManagedVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getManaged() {
    return value.map(ManagedVO::isManaged);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ManagedVO> getManagedValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param managed
   * @return
   */
  public T managed(ManagedVO managed) {
    this.value = Optional.of(managed);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param managed
   * @return
   */
  public T managed(Optional<ManagedVO> managed) {
    this.value = managed;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param managed
   * @return
   */
  public T managed(Boolean managed) {
    this.value = Optional.of(ManagedVO.from(managed));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ManagedVO readManaged(final Optional<ObservedSource> original,
      final ConstraintFailList fails) {
    ManagedVO result = value.orElse(original.map(ObservedSource::getManagedValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "managed", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetManaged() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetManagedIfMatches(final String field) {
    if ("managed".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
